const results = [];
const inputs = $input.all();
const sources = $('Terproses?').all();
for (let i = 0; i < inputs.length; i++) {
  const parsed = inputs[i].json.output || inputs[i].json;
  const slides = (parsed && parsed.slides) ? parsed.slides : [];
  const src = sources[i] ? sources[i].json : {};
  const topik = src.topik || parsed.topik || '';
  const id = src.id || '';
  const email = src.email || '';

  // Bangun ringkasan design system untuk disuntikkan ke tiap image prompt (jaminan konsistensi brand)
  const ds = parsed.design_system || {};
  const c = ds.colors || {};
  const dsParts = [];
  if (ds.style) dsParts.push(ds.style + ' style');
  if (ds.illustration) dsParts.push(ds.illustration);
  if (ds.icon_style) dsParts.push(ds.icon_style + ' icons');
  if (ds.shape) dsParts.push(ds.shape + ' shapes');
  const palette = [c.primary, c.secondary, c.accent, c.background].filter(Boolean).join(', ');
  if (palette) dsParts.push('strict color palette: ' + palette);
  if (ds.alignment) dsParts.push(ds.alignment.toLowerCase() + ' aligned');
  dsParts.push('cohesive brand design system, consistent visual identity across all slides, clean modern professional social media carousel slide');
  const dsSuffix = dsParts.join(', ');

  // Ringkasan design system untuk email
  const dsText = [
    'Style: ' + (ds.style || '-'),
    'Colors: primary ' + (c.primary||'-') + ', secondary ' + (c.secondary||'-') + ', accent ' + (c.accent||'-') + ', background ' + (c.background||'-') + ', neutral ' + (c.neutral||'-'),
    'Typography: heading ' + ((ds.typography||{}).heading||'-') + ', body ' + ((ds.typography||{}).body||'-'),
    'Icon: ' + (ds.icon_style||'-') + ' | Illustration: ' + (ds.illustration||'-') + ' | Shape: ' + (ds.shape||'-'),
    'Border radius: ' + (ds.border_radius||'-') + ' | Alignment: ' + (ds.alignment||'-'),
  ].join('\n');

  const lines = [];
  lines.push('=== DESIGN SYSTEM ===');
  lines.push(dsText);
  lines.push('');
  lines.push('=== SLIDES ===');
  for (const s of slides) {
    lines.push('Slide ' + s.slide_number + ' (' + (s.purpose||'') + '):');
    lines.push('Judul: ' + (s.title || s.headline || ''));
    lines.push('Isi: ' + (s.content || ''));
    if (s.cta) lines.push('CTA: ' + s.cta);
    lines.push('Visual: ' + (s.visual || ''));
    lines.push('');
  }
  const full = lines.join('\n');

  for (const s of slides) {
    const basePrompt = s.image_prompt || '';
    // Sisipkan design system ke image prompt jika belum lengkap
    const finalPrompt = basePrompt + '. ' + dsSuffix;
    results.push({ json: {
      id: id,
      topik: topik,
      email: email,
      full_script: full,
      slide_number: s.slide_number,
      headline: s.title || s.headline || '',
      image_prompt: finalPrompt,
    }});
  }
}
return results;

const data = $input.first().json;
const slides = data.slides || [];
const id = slides.length ? slides[0].id : '';
const topik = slides.length ? slides[0].topik : '';
const script = slides.length ? slides[0].full_script : '';
const fallback = 'product.maxyacademy@gmail.com';
const email = (slides.length && slides[0].email) ? slides[0].email : fallback;
const links = slides.map(s => 'Slide ' + s.slide_number + ' (' + s.headline + '): ' + (s.drive_link || 'uploaded')).join('\n');
return [{ json: {
  id: id,
  to: email,
  subject: 'Carousel siap: ' + topik,
  body: 'Topik: ' + topik + '\n\n=== CAROUSEL SCRIPT (' + slides.length + ' slide) ===\n' + script + '\n\n=== GAMBAR (Google Drive) ===\n' + links,
}}];

// Access the first input item in 'Run Once' mode
const data = $input.first().json;

const output = [];

for (let i = 1; i <= 6; i++) {
  const headingKey = `Slide ${i} Heading`;

  // Get all matching subheadings
  const subheadingKeys = Object.keys(data).filter(key =>
    key.startsWith(`Slide ${i} Sub Heading`)
  );

  const subheadings = subheadingKeys
    .map(key => data[key])
    .filter(value => value && value.trim());

  // Handle CTA keys for Slide 6
  if (subheadings.length === 0 && i === 6) {
    const ctaKeys = Object.keys(data).filter(key =>
      key.startsWith(`Slide 6 CTA`)
    );
    ctaKeys.sort(); // Maintain CTA order
    subheadings.push(
      ...ctaKeys.map(key => data[key]).filter(value => value && value.trim())
    );
  }

  if (data[headingKey] || subheadings.length > 0) {
    output.push({
      json: {
        heading: data[headingKey] || '',
        subheadings,
        slideIndex: i  // ✅ Add the slide index here
      },
    });
  }
}

return output;

const item = $input.first().json;
let links = item.webViewLink || [];
if (!Array.isArray(links)) { links = [links]; }

let linksText = "";
for (let i = 0; i < links.length; i++) {
  linksText += `Slide ${i + 1}: ${links[i]}\n`;
}

return [{ json: { links, linksText, slideCount: links.length } }];

